async (page) => {
  const { exec } = require('child_process');
  const fs = require('fs');

  return new Promise((resolve, reject) => {
    exec('systemctl list-units --type=service --state=running', (error, stdout, stderr) => {
      if (error) {
        reject(`Error: ${error}`);
        return;
      }

      if (stderr) {
        reject(`Stderr: ${stderr}`);
        return;
      }

      fs.writeFileSync('/workspace/services_status.txt', stdout);
      resolve('Services status saved to /workspace/services_status.txt');
    });
  });
}
